package glitch

import data.glitch_lib

# Weak encryption algorithms and protocols to flag
weak_algorithms := {"DES", "3DES", "RC4", "SHA-1", "AES-128", "ECB"}
weak_protocols := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1"}

# Helper to check string values against weak patterns
check_weak_string(value) {
    value.ir_type == "String"
    regex.match(sprintf("(?i).*(%s).*", [concat("|", weak_algorithms)]), value.value)
} else {
    value.ir_type == "String"
    regex.match(sprintf("(?i).*(%s).*", [concat("|", weak_protocols)]), value.value)
}

# Check for weak key sizes
check_weak_key(attr) {
    attr.name == "key_length"
    attr.value.ir_type == "Integer"
    attr.value.value < 2048
} else {
    attr.name == "key_size"
    attr.value.ir_type == "Integer"
    attr.value.value < 2048
} else {
    attr.name == "key_length"
    attr.value.ir_type == "String"
    to_number(attr.value.value) < 2048
} else {
    attr.name == "key_size"
    attr.value.ir_type == "String"
    to_number(attr.value.value) < 2048
}

# Check for disabled encryption
check_disabled_enc(attr) {
    attr.name == "encryption_enabled"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "enable_encryption"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    attr.name == "storage_encrypted"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check for hardcoded secrets
check_hardcoded_secret(attr) {
    attr.value.ir_type == "String"
    regex.match("(?i).*(password|secret|key).*", attr.name)
    length(attr.value.value) > 0
}

# Check for missing key rotation
check_missing_rotation(attr) {
    attr.name == "key_rotation"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check attributes within atomic units for weak encryption
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    check_weak_string(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak encryption algorithm or protocol detected. (CWE-326)"
