package glitch

import data.glitch_lib

# Define weak encryption algorithms and protocols to detect
weak_algorithms := {"DES", "3DES", "RC4", "SHA-1", "AES-128", "ECB", "md5_crypt", "MD5"}
weak_protocols := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1"}
weak_ciphers := {"AES_128_CBC", "TLS_RSA_WITH_AES_128_CBC_SHA"}

# Check for weak string values
check_weak_string(value) {
    value.ir_type == "String"
    regex.match(sprintf("(?i).*(%s).*", [concat("|", weak_algorithms)]), value.value)
} else {
    value.ir_type == "String"
    regex.match(sprintf("(?i).*(%s).*", [concat("|", weak_protocols)]), value.value)
} else {
    value.ir_type == "String"
    regex.match(sprintf("(?i).*(%s).*", [concat("|", weak_ciphers)]), value.value)
}

# Helper to check Value types that might contain strings (String, VariableReference, Access)
check_weak_value(value) {
    value.ir_type == "String"
    check_weak_string(value)
} else {
    value.ir_type == "VariableReference"
    check_weak_string(value)
} else {
    # Check inside Access expressions (e.g., jenkins_user_data['password_md5'])
    value.ir_type == "Access"
    check_weak_value(value.right)
}

# Detect weak encryption in Hash entries (Ansible vars_prompt)
check_hash_weak(entry) {
    entry.key.ir_type == "String"
    entry.key.value == "encrypt"
    entry.value.ir_type == "String"
    check_weak_string(entry.value)
}

# Detect weak encryption in Attributes/Variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, node])
    node.ir_type == "Attribute"
    check_weak_value(node.value)

    result := {
        "type": "sec_weak_crypt",
        "element": node,
